package cn.charlotte.pit.config;

import org.bukkit.inventory.ItemStack;
import org.bukkit.util.io.BukkitObjectInputStream;
import java.io.ByteArrayInputStream;
import java.util.Base64;
import java.util.HashMap;
import java.util.Map;

public class ShopitemConfig {
    private static final Map<Integer, String> ITEM_BASE64_MAP = new HashMap<>();

    static {
        ITEM_BASE64_MAP.put(1, "");
        ITEM_BASE64_MAP.put(2, "");
        ITEM_BASE64_MAP.put(3, "");
        ITEM_BASE64_MAP.put(4, "");
        ITEM_BASE64_MAP.put(5, "");
        ITEM_BASE64_MAP.put(6, "");
        ITEM_BASE64_MAP.put(7, "");
        ITEM_BASE64_MAP.put(8, "");
        ITEM_BASE64_MAP.put(9, "");
        ITEM_BASE64_MAP.put(10, "");
    }


    public static ItemStack getItem(int slot) {
        String base64 = ITEM_BASE64_MAP.get(slot);
        if (base64 == null || base64.isEmpty()) {
            return null;
        }
        try {
            return base64ToItemStack(base64);
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }
    private static ItemStack base64ToItemStack(String base64) throws Exception {
        byte[] decodedBytes = Base64.getDecoder().decode(base64);
        ByteArrayInputStream inputStream = new ByteArrayInputStream(decodedBytes);
        BukkitObjectInputStream dataInput = new BukkitObjectInputStream(inputStream);
        ItemStack item = (ItemStack) dataInput.readObject();
        dataInput.close();
        return item;
    }
}